#[inline]
fn destack_debug_inspector_endpoint_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    handle: resource::InspectorHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        DEBUG_INSPECTOR_ENDPOINT,
        binding.replay_payload_for(DEBUG_INSPECTOR_ENDPOINT)?,
        context,
        |context| platform_runtime_vm::destack_debug_inspector_endpoint(binding, context, handle),
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: InspectorEndpointVm = value.clone();
                let result_recorded_url = {
                    let result_recorded_url_ref = context
                        .string_ref(result_value.url)
                        .map_err(|error| RuntimeError::from(error).boxed())?;
                    result_recorded_url_ref.as_str().to_string()
                };
                let result_recorded_process_id = result_value.process_id;
                let result_recorded = InspectorendpointReplayRecord {
                    url: result_recorded_url,
                    process_id: result_recorded_process_id,
                };
                let payload = DebugInspectorEndpointReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DebugInspectorEndpointReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_url = context
                        .string_handle(value.url.as_str())
                        .map_err(Box::<RuntimeError>::from)?;
                    let vm_result_process_id = value.process_id;
                    let vm_result = InspectorEndpointVm {
                        url: vm_result_url,
                        process_id: vm_result_process_id,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_debug_inspector_endpoint_result(context, result)?;
    Ok(result)
}

