#[inline]
fn destack_debug_profile_snapshot_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    handle: resource::ProfileHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        DEBUG_PROFILE_SNAPSHOT,
        binding.replay_payload_for(DEBUG_PROFILE_SNAPSHOT)?,
        context,
        |context| platform_runtime_vm::destack_debug_profile_snapshot(binding, context, handle),
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmArray<u8> = value.clone();
                let result_recorded = result_value.read_bytes(context)?;
                let payload = DebugProfileSnapshotReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DebugProfileSnapshotReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = VmArray::<u8>::from_bytes(context, value.as_ref())?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_debug_profile_snapshot_result(context, result)?;
    Ok(result)
}

